const app=document.getElementById('app');
const cyber=[{tag:'01 / THE THREAT',title:'ما هو الأمن السيبراني؟',desc:'الأمن السيبراني هو حماية الأنظمة والشبكات والبيانات من الوصول غير المصرح به والتعطيل والسرقة. يشمل حماية الأجهزة، تدريب المستخدمين، وإدارة المخاطر.',explain:'في هذه الصفحة أعرّف الأمن السيبراني وأوضح أنه ليس برنامجاً واحداً، بل مجموعة من الأشخاص والتقنيات والإجراءات التي تحمي المعلومات.'},{tag:'02 / THE ATTACK SURFACE',title:'كيف تبدأ التهديدات؟',desc:'قد تبدأ الحوادث برسالة تصيد، كلمة مرور ضعيفة، تحديث مفقود أو مشاركة معلومات حساسة. نعرض سيناريوهات تعليمية آمنة لفهم إشارات الخطر.',explain:'الهدف من هذا الفصل هو معرفة أساليب الخداع الرقمي وتعلّم التعرف عليها، وليس تنفيذ هجمات حقيقية.'},{tag:'03 / DEFENSE IN DEPTH',title:'طبقات الحماية',desc:'تعمل المصادقة متعددة العوامل والتحديثات والنسخ الاحتياطية ومبدأ أقل الصلاحيات معاً لتقليل المخاطر. لا توجد وسيلة حماية واحدة كافية.',explain:'هنا أشرح مبدأ الدفاع متعدد الطبقات: إذا فشلت طبقة، تبقى طبقات أخرى تساعد على حماية النظام.'},{tag:'04 / INCIDENT RESPONSE',title:'كيف نستجيب لحادث أمني؟',desc:'نحدد المؤشرات، نحتوي المشكلة، نحافظ على الأدلة، نعالج السبب، ثم نستعيد الخدمة ونتعلم من الحادث. هذه محاكاة تعليمية وليست نظام مراقبة حقيقياً.',explain:'أشرح كيف تساعد خطة الاستجابة المنظمة على تقليل الضرر عند وقوع حادث، ولماذا توثيق ما حدث مهم.'}];
const python=[{tag:'01 / INTRODUCTION',title:'ليش نتعلم Python؟',desc:'بايثون لغة برمجة واضحة وسهلة القراءة، تستخدم في الأتمتة وتحليل البيانات والويب والذكاء الاصطناعي. تبدأ من الأوامر البسيطة وتصل إلى مشاريع كبيرة.',code:'print("Hello, Cybernex!")',explain:'اخترت لغة بايثون لأنها مناسبة للمبتدئين وتساعدنا على فهم التفكير المنطقي وحل المشكلات.'},{tag:'02 / VARIABLES',title:'المتغيرات وأنواع البيانات',desc:'المتغير اسم نخزن فيه قيمة. قد تكون القيمة نصاً أو عدداً أو قيمة منطقية. نستخدمها لتنظيم المعلومات داخل البرنامج.',code:'name = "Bader"\nlevel = 10\nprint(name)\nprint(level)',explain:'هنا أوضح أن المتغيرات تخزن بيانات يمكن استخدامها وتغييرها أثناء تشغيل البرنامج.'},{tag:'03 / CONDITIONS',title:'الشروط واتخاذ القرار',desc:'تسمح if وelse للبرنامج باختيار سلوك مختلف حسب تحقق شرط معين. المسافات البادئة جزء أساسي من صياغة بايثون.',code:'score = 85\nif score >= 60:\n    print("Passed")\nelse:\n    print("Try again")',explain:'أشرح كيف تتخذ البرامج قرارات باستخدام الشروط، مع مثال بسيط عن نتيجة اختبار.'},{tag:'04 / LOOPS',title:'الحلقات والتكرار',desc:'تستخدم حلقة for لتكرار أمر على مجموعة قيم. وهي مفيدة عند معالجة قوائم أو تنفيذ خطوات متشابهة.',code:'for i in range(1, 4):\n    print(i)',explain:'هنا أشرح أن الحلقة توفر علينا تكرار كتابة نفس السطر، وتنفذ أمراً عدة مرات.'},{tag:'05 / FUNCTIONS',title:'الدوال وتنظيم المشاريع',desc:'الدالة مجموعة أوامر لها اسم ويمكن استدعاؤها أكثر من مرة. تساعدنا على كتابة برامج مرتبة وأسهل للصيانة.',code:'def greet(name):\n    print("Hello " + name)\ngreet("Student")',explain:'أوضح كيف نقسم البرنامج إلى أجزاء صغيرة قابلة لإعادة الاستخدام، وهذا من أساسيات البرمجة الجيدة.'}];
const card=(x,i)=>`<section class="section ${i%2?'alternate':''}" id="lesson-${i}"><div class="content glass"><div class="kicker">${x.tag}</div><h2>${x.title}</h2><p>${x.desc}</p>${x.code?`<div class="terminal"><div class="termbar">PYTHON / EXAMPLE</div><pre>${x.code}</pre></div>`:''}<button class="btn tiny explainbtn" data-explain="${i}">نص الشرح للأستاذ</button><div class="explain" id="explain-${i}">${x.explain}</div></div></section>`;
app.innerHTML=`<canvas id="scene" aria-hidden="true"></canvas><div id="shade"></div><div class="intro" id="intro"><h1>CYBERNEX</h1><p>INITIALIZING DIGITAL EXPERIENCE</p><div class="progress"><span id="progress"></span></div><button class="btn tiny" id="skip">تجاوز المقدمة</button></div><div class="transition" id="transition">PYTHON LAB</div><header class="top"><a class="brand" href="#home"><div class="logo">C</div><div><strong>CYBERNEX</strong><small>SECURITY × CODE</small></div></a><nav id="nav"><a href="#home">الرئيسية</a><a href="#vision">فكرة المشروع</a><a href="#lessons">الفصول</a><a href="#lab">المختبر</a><button class="btn tiny" id="switchNav">PYTHON LAB ↗</button><button class="btn tiny" id="present">وضع العرض</button></nav><button class="btn mobilemenu" id="menu" aria-label="القائمة">☰</button></header><main><div class="cyberpage"><section class="section hero" id="home"><div class="content"><div class="kicker">AN IMMERSIVE CYBERSECURITY EXPERIENCE</div><h1>CYBERNEX</h1><div class="subtitle">افهم التهديد. صمّم الدفاع. تعلّم البرمجة.</div><p>رحلة علمية داخل عالم الأمن السيبراني: من التهديدات الرقمية إلى استراتيجيات الحماية والاستجابة للحوادث. استكشف الشبكات ثلاثية الأبعاد ثم انتقل إلى مختبر Python.</p><div class="actions"><a class="btn primary" href="#vision">ابدأ الاستكشاف ←</a><button class="btn" id="switchHero">ادخل عالم Python ↗</button></div><div class="stats"><div><b>04</b><small>فصول أمن سيبراني</small></div><div><b>05</b><small>دروس Python</small></div><div><b>3D</b><small>مشهد تفاعلي</small></div></div></div><div class="scroll">SCROLL TO EXPLORE</div></section><section class="section" id="vision"><div class="content glass"><div class="kicker">THE PURPOSE / 00</div><h2>ليش صممت CYBERNEX؟</h2><p>لأن حياتنا تعتمد على التكنولوجيا، أصبحت حماية المعلومات وفهم البرمجة مهارتين أساسيتين. صممت هذا المشروع لأحوّل المفاهيم التقنية إلى تجربة مرئية وتفاعلية، تساعد الطلاب على التعلم وتوضح أهمية الاستخدام المسؤول للتقنية.</p><button class="btn tiny explainbtn" data-explain="vision">نص الشرح للأستاذ</button><div class="explain" id="explain-vision">السلام عليكم. مشروعي CYBERNEX يجمع بين الأمن السيبراني ولغة بايثون. اخترته لأن حماية المعلومات وفهم البرمجة أصبحا من المهارات المهمة، وأردت تقديمهما بأسلوب تفاعلي يساعد على الفهم.</div></div></section><section class="section" id="lessons"><div class="content wide"><div class="kicker">SECURITY ARCHITECTURE</div><h2>أربعة محاور لفهم الحماية الرقمية</h2><div class="cards">${cyber.slice(0,3).map((c,i)=>`<a class="card" href="#cyber-${i}"><div class="symbol">0${i+1} ◈</div><h3>${c.title}</h3><p>${c.desc}</p></a>`).join('')}</div></div></section>${cyber.map((c,i)=>`<section class="section" id="cyber-${i}"><div class="content glass"><div class="kicker">${c.tag}</div><h2>${c.title}</h2><p>${c.desc}</p><button class="btn tiny explainbtn" data-explain="cyber-${i}">نص الشرح للأستاذ</button><div class="explain" id="explain-cyber-${i}">${c.explain}</div></div></section>`).join('')}<section class="section" id="lab"><div class="content wide"><div class="kicker">SECURITY OPERATIONS / LIVE SIMULATION</div><h2>مركز الاستجابة للحوادث</h2><div class="two"><div class="glass"><span class="tag">محاكاة دفاعية آمنة</span><h3>سيناريو: رسالة تطلب كلمة مرورك</h3><p>وصلك بريد يبدو أنه من قسم الدعم ويطلب تسجيل الدخول فوراً عبر رابط غير معروف. شنو التصرف الصحيح؟</p><button class="choice" data-answer="0">أضغط الرابط وأدخل كلمة المرور</button><button class="choice" data-answer="1">أتحقق من المصدر عبر القنوات الرسمية وأبلغ عن الرسالة</button><button class="choice" data-answer="2">أرسل الرسالة إلى كل زملائي</button><div class="feedback" id="securityFeedback">اختر قرارك لعرض التحليل.</div></div><div class="glass"><div class="kicker">RISK MODEL</div><h3>تقييم الحماية الافتراضي</h3><div class="labelrow"><span>تفعيل المصادقة متعددة العوامل</span><span id="mfaValue">50%</span></div><input class="range" type="range" id="mfa" min="0" max="100" value="50"><div class="labelrow"><span>تحديث الأجهزة والأنظمة</span><span id="patchValue">50%</span></div><input class="range" type="range" id="patch" min="0" max="100" value="50"><div class="labelrow"><span>مؤشر افتراضي للتوعية والحماية</span><span id="riskValue">50 / 100</span></div><div class="bar"><span id="riskBar" style="width:50%"></span></div><p style="font-size:12px">هذا مؤشر تعليمي مبسط بمتوسط القيمتين، وليس تقييماً أمنياً حقيقياً.</p></div></div></div></section><section class="section" id="bridge"><div class="content glass"><div class="kicker">THE NEXT DIMENSION</div><h2>من حماية الأنظمة إلى برمجتها</h2><p>فهم البرمجة يساعدنا على التفكير المنطقي وفهم كيفية بناء الأدوات الرقمية. انتقل إلى عالم Python واستكشف أولى خطوات كتابة الكود.</p><button class="btn primary" id="switchBridge">انتقل إلى PYTHON LAB ↗</button></div></section></div><div class="pythonpage"><section class="section hero" id="pythonHome"><div class="content"><div class="kicker">CODE IS A SUPERPOWER / PYTHON WORLD</div><h1 style="font-size:clamp(55px,10vw,135px)">PYTHON</h1><div class="subtitle">من أول سطر إلى أول برنامج.</div><p>عالم تفاعلي لتعلّم أساسيات لغة Python مع أمثلة واضحة، محرر تجريبي آمن، واختبارات قصيرة تساعدك على فهم التفكير البرمجي.</p><div class="actions"><a class="btn primary" href="#pythonVision">ابدأ تعلم Python ←</a><button class="btn" id="backHero">العودة للأمن السيبراني ↗</button></div></div><div class="scroll">SCROLL TO CODE</div></section><section class="section" id="pythonVision"><div class="content glass"><div class="kicker">WHY PYTHON / 00</div><h2>ليش Python بالذات؟</h2><p>لأن صياغتها واضحة وتستخدم في مجالات عديدة، من أتمتة المهام إلى تحليل البيانات. سنتعلم المتغيرات والشروط والحلقات والدوال، ونربط كل فكرة بتجربة عملية.</p><button class="btn tiny explainbtn" data-explain="pyvision">نص الشرح للأستاذ</button><div class="explain" id="explain-pyvision">اخترت بايثون لأنها لغة مناسبة للمبتدئين وتساعد على تعلم المنطق البرمجي. وفي هذا القسم أشرح أساسياتها بأمثلة تفاعلية.</div></div></section>${python.map((c,i)=>`<section class="section" id="py-${i}"><div class="content glass"><div class="kicker">${c.tag}</div><h2>${c.title}</h2><p>${c.desc}</p><div class="terminal"><div class="termbar"><span class="dots"><i></i><i></i><i></i></span> example_${i+1}.py</div><pre>${c.code}</pre></div><button class="btn tiny explainbtn" data-explain="py-${i}">نص الشرح للأستاذ</button><div class="explain" id="explain-py-${i}">${c.explain}</div></div></section>`).join('')}<section class="section" id="pythonLab"><div class="content wide"><div class="kicker">INTERACTIVE CODE LAB</div><h2>مختبر Python المصغر</h2><p>اكتب أو عدّل المثال وشغّله. هذا محرر تعليمي محدود وآمن يدعم أوامر <code>print</code> البسيطة والمتغيرات النصية والعددية، وليس مفسّر Python كاملاً.</p><div class="terminal"><div class="termbar"><span class="dots"><i></i><i></i><i></i></span> playground.py — Safe Demo</div><textarea id="editor" spellcheck="false" aria-label="محرر الكود">name = "CyberNex"\nprint("Hello")\nprint(name)</textarea><div class="output" id="output">اضغط تشغيل لعرض النتيجة...</div></div><div class="actions"><button class="btn primary" id="run">▶ تشغيل المثال</button><button class="btn" id="resetCode">إعادة المثال</button></div><p style="font-size:12px">لا يتم تنفيذ تعليمات Python أو JavaScript عشوائية، ولا تُرسل الشيفرة إلى خادم.</p></div></section><section class="section" id="quiz"><div class="content glass"><div class="kicker">KNOWLEDGE CHECK</div><h2>اختبر معلوماتك</h2><p>ما وظيفة الدالة <code>print()</code> في Python؟</p><button class="choice" data-quiz="0">حذف الملفات</button><button class="choice" data-quiz="1">عرض قيمة أو نص في المخرجات</button><button class="choice" data-quiz="2">إيقاف الكمبيوتر</button><div class="feedback" id="quizFeedback">اختر إجابتك.</div></div></section><section class="section" id="conclusion"><div class="content glass"><div class="kicker">THE FINAL CHAPTER</div><h2>التقنية مسؤولية قبل أن تكون قوة</h2><p>تعلمنا أن حماية الأنظمة تتطلب وعياً ومهارات، وأن البرمجة تساعدنا على بناء حلول جديدة. هدف CYBERNEX هو إلهام الطلاب للتعلم والاستخدام المسؤول للتكنولوجيا.</p><div class="actions"><button class="btn primary" id="presentBottom">ابدأ العرض للأستاذ</button><button class="btn" id="backBottom">العودة إلى الأمن السيبراني</button></div></div></section></div></main><footer class="footer"><div><strong>CYBERNEX</strong><div>CYBERSECURITY × PYTHON / STUDENT INNOVATION PROJECT</div></div><div><button class="btn tiny" id="motion">تقليل الحركة</button> <span>© 2026 CYBERNEX</span></div></footer><div class="overlay" id="slides" role="dialog" aria-modal="true" aria-label="عرض المشروع"><div class="slide"><div class="kicker" id="slideTag"></div><h2 id="slideTitle"></h2><p id="slideText"></p><div class="slidecontrols"><button class="btn primary" id="next">التالي ←</button><button class="btn" id="prev">السابق →</button><button class="btn" id="close">إغلاق ✕</button><span id="slideCount"></span></div></div></div></div>`;
const $=s=>document.querySelector(s);
$('#menu').onclick=()=>$('#nav').classList.toggle('open');$('#nav').querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>$('#nav').classList.remove('open')));
document.querySelectorAll('[data-explain]').forEach(b=>b.onclick=()=>$('#explain-'+b.dataset.explain).classList.toggle('show'));
let isPython=false,reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function switchWorld(target){if(isPython===target)return;const change=()=>{isPython=target;document.body.classList.toggle('python',target);$('#switchNav').textContent=target?'CYBER DEFENSE ↗':'PYTHON LAB ↗';$('#transition').textContent=target?'PYTHON LAB':'CYBER DEFENSE';window.scrollTo({top:0,behavior:'instant'});$('#nav').classList.remove('open');if(window.ScrollTrigger)window.ScrollTrigger.refresh()};if(reduced||!window.gsap){change();return}const overlay=$('#transition');gsap.timeline().set(overlay,{display:'grid'}).to(overlay,{opacity:1,duration:.55,ease:'power3.inOut'}).call(change).to(overlay,{opacity:0,duration:.65,delay:.25,ease:'power3.inOut'}).set(overlay,{display:'none'});}
['switchNav','switchHero','switchBridge'].forEach(id=>$('#'+id).onclick=()=>switchWorld(!isPython));['backHero','backBottom'].forEach(id=>$('#'+id).onclick=()=>switchWorld(false));
const updateRisk=()=>{let a=+$('#mfa').value,b=+$('#patch').value,s=Math.round((a+b)/2);$('#mfaValue').textContent=a+'%';$('#patchValue').textContent=b+'%';$('#riskValue').textContent=s+' / 100';$('#riskBar').style.width=s+'%'};$('#mfa').oninput=updateRisk;$('#patch').oninput=updateRisk;
document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-answer]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');$('#securityFeedback').textContent=b.dataset.answer==='1'?'قرار صحيح: تحقق من المصدر عبر قناة رسمية وأبلغ عن محاولة التصيد.':'هذا قرار غير آمن. لا تفتح الروابط المجهولة ولا تعيد نشر رسائل التصيد.'});
document.querySelectorAll('[data-quiz]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-quiz]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');$('#quizFeedback').textContent=b.dataset.quiz==='1'?'إجابة صحيحة! print() تعرض المخرجات.':'جرّب مرة ثانية. فكر في وظيفة عرض النتائج.'});
const initial='name = "CyberNex"\nprint("Hello")\nprint(name)';$('#resetCode').onclick=()=>{$('#editor').value=initial;$('#output').textContent='تمت إعادة المثال.'};
function runSafeDemo(source){const vars={};const lines=source.split(/\r?\n/);if(lines.length>30||source.length>1500)throw Error('الحد الأقصى 30 سطراً و1500 حرف.');const out=[];for(const raw of lines){const line=raw.trim();if(!line||line.startsWith('#'))continue;let m=line.match(/^([A-Za-z_]\w*)\s*=\s*("[^"\n]*"|'[^'\n]*'|-?\d+(?:\.\d+)?)$/);if(m){vars[m[1]]=m[2][0]==='"'||m[2][0]==="'"?m[2].slice(1,-1):Number(m[2]);continue}m=line.match(/^print\((.*)\)$/);if(m){const expr=m[1].trim();if(/^"[^"\n]*"$|^'[^'\n]*'$/.test(expr))out.push(expr.slice(1,-1));else if(/^-?\d+(?:\.\d+)?$/.test(expr))out.push(expr);else if(Object.prototype.hasOwnProperty.call(vars,expr))out.push(String(vars[expr]));else throw Error('المثال يدعم نصاً أو رقماً أو اسم متغير داخل print فقط.');continue}throw Error('تعليمة غير مدعومة في المحرر التجريبي: '+line.slice(0,50))}return out.join('\n')||'(لا توجد مخرجات)'}
$('#run').onclick=()=>{try{$('#output').textContent=runSafeDemo($('#editor').value)}catch(e){$('#output').textContent='Error: '+e.message}};
