async function init3D(){try{const THREE=await import('./vendor/three.module.js');const canvas=$('#scene');const renderer=new THREE.WebGLRenderer({canvas,alpha:true,antialias:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.setSize(innerWidth,innerHeight);renderer.outputColorSpace=THREE.SRGBColorSpace;const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(44,innerWidth/innerHeight,.1,150);camera.position.set(0,0,14);scene.add(new THREE.AmbientLight(0x8bdfff,1.3));const a=new THREE.PointLight(0x42e9d8,85,30);a.position.set(5,5,7);scene.add(a);const b=new THREE.PointLight(0x447dff,65,30);b.position.set(-5,-3,4);scene.add(b);const group=new THREE.Group();scene.add(group);const mat=new THREE.MeshStandardMaterial({color:0x12384c,metalness:.8,roughness:.2}),edge=new THREE.MeshStandardMaterial({color:0x56e4d6,emissive:0x118e8b,emissiveIntensity:1.6,metalness:.6,roughness:.2}),gold=new THREE.MeshStandardMaterial({color:0xffd16b,emissive:0x996519,emissiveIntensity:1.4,metalness:.6,roughness:.22});let parts=[];function add(geo,material,x,y,z,ox,oy,oz){let mesh=new THREE.Mesh(geo,material);mesh.position.set(x,y,z);group.add(mesh);parts.push({mesh,base:new THREE.Vector3(x,y,z),offset:new THREE.Vector3(ox,oy,oz)});return mesh}const core=new THREE.IcosahedronGeometry(2.05,1);add(core,mat,0,0,0,0,0,-8);for(let i=0;i<18;i++){const angle=i*Math.PI*2/18;let radius=2.7+(i%3)*.27;const mesh=add(new THREE.BoxGeometry(.26,1.3,.28),i%4===0?edge:mat,Math.cos(angle)*radius,Math.sin(angle)*radius,0,Math.cos(angle)*5,Math.sin(angle)*5,(i%2?5:-5));mesh.rotation.z=angle-Math.PI/2}for(let i=0;i<12;i++){let angle=i*Math.PI*2/12;const p=add(new THREE.SphereGeometry(.14,12,10),edge,Math.cos(angle)*2.05,Math.sin(angle)*2.05,1.1,Math.cos(angle)*6,Math.sin(angle)*6,6)}const rings=[];for(let r of [3.4,4.1,4.8]){let ring=new THREE.Mesh(new THREE.TorusGeometry(r,.015,5,160),new THREE.MeshBasicMaterial({color:0x46bfc8,transparent:true,opacity:.35}));ring.rotation.x=.35;group.add(ring);rings.push(ring)}const stars=new THREE.BufferGeometry(),pos=new Float32Array(750*3);for(let i=0;i<pos.length;i++)pos[i]=(Math.random()-.5)*50;stars.setAttribute('position',new THREE.BufferAttribute(pos,3));scene.add(new THREE.Points(stars,new THREE.PointsMaterial({color:0x62b1cd,size:.026,transparent:true,opacity:.65})));let active=true,raf,smoothed=0;function tick(){if(!active)return;if(document.hidden||window.cxPrefs?.motion==='off'||window.cxPrefs?.background!=='full'||document.body.dataset.view!=='world'){raf=setTimeout(tick,400);return;}const h=Math.max(1,document.documentElement.scrollHeight-innerHeight),progress=scrollY/h;smoothed+=(progress-smoothed)*.055;const phase=Math.min(1,Math.max(0,(smoothed+.05)*3.7));parts.forEach((p,i)=>{let v=THREE.MathUtils.smoothstep(phase,i/parts.length*.6,Math.min(1,i/parts.length*.6+.45));p.mesh.position.copy(p.base).addScaledVector(p.offset,1-v);p.mesh.rotation.y=(1-v)*2});group.rotation.y=smoothed*5+performance.now()*.00014;group.rotation.z=smoothed*1.7;group.position.x=innerWidth<900?0:-2.8;group.scale.setScalar(innerWidth<900?.68:1);rings.forEach((r,i)=>r.rotation.y=performance.now()*.0001*(i%2?1:-1));edge.color.setHex(isPython?0xffd46b:0x56e4d6);renderer.render(scene,camera);raf=requestAnimationFrame(tick)}tick();window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});document.addEventListener('visibilitychange',()=>{if(document.hidden){active=false;cancelAnimationFrame(raf)}else if(!active){active=true;tick()}})}catch(e){console.warn('3D unavailable; site remains functional',e);$('#scene').style.display='none'}}init3D();

