   nodes.forEach((n,i)=>{const x=n.x*w,y=n.y*h,bad=i===4&&!contained;const col=bad?'#ff8395':i===selected?'#ffffff':'#6af2ef';const radius=i===0?21:15;ctx.beginPath();ctx.arc(x,y,radius+7+Math.sin(t*.003+i)*2,0,Math.PI*2);ctx.strokeStyle=bad?'rgba(255,100,120,.45)':'rgba(106,242,239,.2)';ctx.lineWidth=2;ctx.stroke();ctx.beginPath();ctx.arc(x,y,radius,0,Math.PI*2);ctx.fillStyle=bad?'#612b4a':'#114765';ctx.fill();ctx.strokeStyle=col;ctx.lineWidth=2;ctx.stroke();ctx.fillStyle=col;ctx.font='bold 12px Cairo, sans-serif';ctx.textAlign='center';ctx.fillText(i===0?'⌘':bad?'!':i===4&&contained?'✓':'●',x,y+4);ctx.font='11px Cairo, sans-serif';ctx.fillStyle='#e9faff';ctx.fillText(n.name,x,y+radius+20)});
